SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsJournalSummaryRow
{
    InventJournalId     journalId;
    InventJournalNameId journalNameId;
    Description          description;
    TransDate            journalDate;
    int                  lineCount;
    str                  transferMode;
    List                 claims;
    List                 ranges;
    boolean              locationFirst;
    boolean              zeroStockCheck;

    str countMode;
    int passNumber;
    int recountLines;
    str recountOf;
    str originType;
    int priority;
    str toleranceInfo;
    str abcClass;
    str freezeState;
    utcdatetime snapshotAtUtc;
    str controlGroupId;
    str repeatInfo;
    str doneNote;
}

Method.Source:
[DataMemberAttribute('RecountLines')]
public int parmRecountLines(int _value = recountLines)
{
    recountLines = _value;
    return recountLines;
}

[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('JournalNameId')]
public InventJournalNameId parmJournalNameId(InventJournalNameId _value = journalNameId)
{
    journalNameId = _value;
    return journalNameId;
}

[DataMemberAttribute('Description')]
public Description parmDescription(Description _value = description)
{
    description = _value;
    return description;
}

[DataMemberAttribute('JournalDate')]
public TransDate parmJournalDate(TransDate _value = journalDate)
{
    journalDate = _value;
    return journalDate;
}

/// <summary>
/// Line count only - never the lines themselves. This row powers the list screen; a journal's
/// lines are fetched separately, in bulk, once the worker actually opens it (see
/// HSMobileOpsCountingService's own class doc for why that split exists).
/// </summary>
[DataMemberAttribute('LineCount')]
public int parmLineCount(int _value = lineCount)
{
    lineCount = _value;
    return lineCount;
}

/// <summary>
/// DMF (bulk export/import) or DIRECT (lines and counts via HSMobileOpsCountTaskSvc).
/// Decided here, per journal - never on the device.
/// </summary>
[DataMemberAttribute('TransferMode')]
public str parmTransferMode(str _value = transferMode)
{
    transferMode = _value;
    return transferMode;
}

[DataMemberAttribute('Claims'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsCountClaimRow))]
public List parmClaims(List _value = claims)
{
    claims = _value;
    return claims;
}

[DataMemberAttribute('Ranges'),
 DataCollectionAttribute(Types::Class, classStr(HSMobileOpsCountRangeRow))]
public List parmRanges(List _value = ranges)
{
    ranges = _value;
    return ranges;
}

/// <summary>
/// Count this journal location by location: scan a location, then its items.
/// </summary>
[DataMemberAttribute('LocationFirst')]
public boolean parmLocationFirst(boolean _value = locationFirst)
{
    locationFirst = _value;
    return locationFirst;
}

/// <summary>
/// A zero-stock verification journal: the system expects these locations to be empty; the
/// counter confirms empty or records what was found.
/// </summary>
[DataMemberAttribute('ZeroStockCheck')]
public boolean parmZeroStockCheck(boolean _value = zeroStockCheck)
{
    zeroStockCheck = _value;
    return zeroStockCheck;
}

/// <summary>
/// SINGLE, or DOUBLE_BLIND: two independent passes by two users, kept by the
/// server in its attempt table. Decided here, never on the device.
/// </summary>
[DataMemberAttribute('CountMode')]
public str parmCountMode(str _value = countMode)
{
    countMode = _value;
    return countMode;
}

/// <summary>
/// 1 for a first count, 2+ for a recount or second pass.
/// </summary>
[DataMemberAttribute('PassNumber')]
public int parmPassNumber(int _value = passNumber)
{
    passNumber = _value;
    return passNumber;
}

/// <summary>
/// For a RECOUNT journal: the journal it recounts.
/// </summary>
[DataMemberAttribute('RecountOf')]
public str parmRecountOf(str _value = recountOf)
{
    recountOf = _value;
    return recountOf;
}

/// <summary>
/// Why this count exists: SCHEDULED, PERIODIC, SPOT, TRIGGERED, OPPORTUNITY, CONTROL_GROUP or RECOUNT.
/// </summary>
[DataMemberAttribute('OriginType')]
public str parmOriginType(str _value = originType)
{
    originType = _value;
    return originType;
}

/// <summary>
/// Higher first. Decided here (TRIGGERED, SPOT and RECOUNT above SCHEDULED), never on the device.
/// </summary>
[DataMemberAttribute('Priority')]
public int parmPriority(int _value = priority)
{
    priority = _value;
    return priority;
}

/// <summary>
/// Display-only text describing the tolerance that applies, e.g. 'Class A: 2% / 50 AED'.
/// </summary>
[DataMemberAttribute('ToleranceInfo')]
public str parmToleranceInfo(str _value = toleranceInfo)
{
    toleranceInfo = _value;
    return toleranceInfo;
}

/// <summary>
/// Display-only ABC class of the journal's items, when uniform.
/// </summary>
[DataMemberAttribute('AbcClass')]
public str parmAbcClass(str _value = abcClass)
{
    abcClass = _value;
    return abcClass;
}

/// <summary>
/// NONE, LOCATION_FROZEN (stock movements blocked at the counted locations) or SNAPSHOT_ONLY
/// (the count is measured against stock at SnapshotAtUtc).
/// </summary>
[DataMemberAttribute('FreezeState')]
public str parmFreezeState(str _value = freezeState)
{
    freezeState = _value;
    return freezeState;
}

/// <summary>
/// SNAPSHOT_ONLY: the moment the count is measured against.
/// </summary>
[DataMemberAttribute('SnapshotAtUtc')]
public utcdatetime parmSnapshotAtUtc(utcdatetime _value = snapshotAtUtc)
{
    snapshotAtUtc = _value;
    return snapshotAtUtc;
}

/// <summary>
/// CONTROL_GROUP journals: the fixed item/location sample this journal repeats.
/// </summary>
[DataMemberAttribute('ControlGroupId')]
public str parmControlGroupId(str _value = controlGroupId)
{
    controlGroupId = _value;
    return controlGroupId;
}

/// <summary>
/// Display-only description of the repeat, e.g. 'Repeats weekly'.
/// </summary>
[DataMemberAttribute('RepeatInfo')]
public str parmRepeatInfo(str _value = repeatInfo)
{
    repeatInfo = _value;
    return repeatInfo;
}

/// <summary>
/// Set only on a journal finished for this user, listed when the request asks for them:
/// when it was posted, or what it is waiting for. Blank on every open journal.
/// </summary>
[DataMemberAttribute('DoneNote')]
public str parmDoneNote(str _value = doneNote)
{
    doneNote = _value;
    return doneNote;
}
